CREATE TYPE "delivery_job_status" AS ENUM('draft','ready_for_dispatch','assigned','out_for_delivery','delivered','delivery_failed','canceled');
CREATE TYPE "delivery_stop_status" AS ENUM('pending','assigned','out_for_delivery','delivered','delivery_failed','canceled');
CREATE TYPE "delivery_proof_type" AS ENUM('recipient_name','signature','photo','otp');
CREATE TABLE "delivery_drivers" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"tenant_id" uuid NOT NULL REFERENCES "tenants"("id") ON DELETE CASCADE,"member_id" uuid REFERENCES "members"("id") ON DELETE SET NULL,"name" text NOT NULL,"phone" text NOT NULL,"email" text,"active" boolean NOT NULL DEFAULT true,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "delivery_vehicles" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"tenant_id" uuid NOT NULL REFERENCES "tenants"("id") ON DELETE CASCADE,"registration" text NOT NULL,"name" text NOT NULL,"capacity_kg" integer,"active" boolean NOT NULL DEFAULT true,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "delivery_jobs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"tenant_id" uuid NOT NULL REFERENCES "tenants"("id") ON DELETE CASCADE,"reference" text NOT NULL,"status" "delivery_job_status" NOT NULL DEFAULT 'draft',"scheduled_date" timestamptz NOT NULL,"recipient_name" text NOT NULL,"recipient_phone" text,"recipient_email" text,"address" jsonb NOT NULL,"delivery_notes" text NOT NULL DEFAULT '',"created_by_member_id" uuid NOT NULL REFERENCES "members"("id"),"completed_at" timestamptz,"canceled_at" timestamptz,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "delivery_stops" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"tenant_id" uuid NOT NULL REFERENCES "tenants"("id") ON DELETE CASCADE,"delivery_job_id" uuid NOT NULL REFERENCES "delivery_jobs"("id") ON DELETE CASCADE,"sequence" integer NOT NULL DEFAULT 1,"status" "delivery_stop_status" NOT NULL DEFAULT 'pending',"recipient_name" text NOT NULL,"address" jsonb NOT NULL,"scheduled_window_start" timestamptz,"scheduled_window_end" timestamptz,"completed_at" timestamptz,"failure_reason" text,"notes" text NOT NULL DEFAULT '');
CREATE TABLE "delivery_assignments" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"tenant_id" uuid NOT NULL REFERENCES "tenants"("id") ON DELETE CASCADE,"delivery_job_id" uuid NOT NULL REFERENCES "delivery_jobs"("id") ON DELETE CASCADE,"delivery_driver_id" uuid NOT NULL REFERENCES "delivery_drivers"("id"),"delivery_vehicle_id" uuid REFERENCES "delivery_vehicles"("id"),"assigned_by_member_id" uuid NOT NULL REFERENCES "members"("id"),"assigned_at" timestamptz NOT NULL DEFAULT now(),"unassigned_at" timestamptz);
CREATE TABLE "delivery_proofs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"tenant_id" uuid NOT NULL REFERENCES "tenants"("id") ON DELETE CASCADE,"delivery_stop_id" uuid NOT NULL REFERENCES "delivery_stops"("id") ON DELETE CASCADE,"type" "delivery_proof_type" NOT NULL,"recipient_name" text,"storage_key" text,"captured_at" timestamptz NOT NULL DEFAULT now(),"captured_by_member_id" uuid REFERENCES "members"("id") ON DELETE SET NULL,"metadata" jsonb NOT NULL DEFAULT '{}');
CREATE TABLE "delivery_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"tenant_id" uuid NOT NULL REFERENCES "tenants"("id") ON DELETE CASCADE,"delivery_job_id" uuid NOT NULL REFERENCES "delivery_jobs"("id") ON DELETE CASCADE,"delivery_stop_id" uuid REFERENCES "delivery_stops"("id") ON DELETE CASCADE,"event_type" text NOT NULL,"actor_member_id" uuid REFERENCES "members"("id") ON DELETE SET NULL,"occurred_at" timestamptz NOT NULL DEFAULT now(),"metadata" jsonb NOT NULL DEFAULT '{}');
CREATE TABLE "delivery_tracking_tokens" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"tenant_id" uuid NOT NULL REFERENCES "tenants"("id") ON DELETE CASCADE,"delivery_job_id" uuid NOT NULL REFERENCES "delivery_jobs"("id") ON DELETE CASCADE,"token_hash" text NOT NULL UNIQUE,"expires_at" timestamptz,"revoked_at" timestamptz,"last_viewed_at" timestamptz,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "delivery_driver_member_tenant_idx" ON "delivery_drivers" ("tenant_id","member_id");
CREATE UNIQUE INDEX "delivery_vehicle_registration_tenant_idx" ON "delivery_vehicles" ("tenant_id","registration");
CREATE UNIQUE INDEX "delivery_job_reference_tenant_idx" ON "delivery_jobs" ("tenant_id","reference");
CREATE UNIQUE INDEX "delivery_stop_sequence_job_idx" ON "delivery_stops" ("delivery_job_id","sequence");
CREATE UNIQUE INDEX "active_delivery_assignment_job_idx" ON "delivery_assignments" ("delivery_job_id") WHERE "unassigned_at" IS NULL;